-- Clear Talks CT-02e: DRAFT/UNAPPLIED production migration.
-- Migration filename generated by Supabase CLI v3.2.0, GitHub CI #45292742893.
-- Requires CT-02b and CT-02c first, independently approved owner + role grants.
-- DO NOT APPLY WITHOUT VERIFIED BACKUP, MIGRATION HISTORY RECONCILIATION,
-- EXISTING PUBLISH RPC/STORAGE/VERSIONS CUTOVER AND EXPLICIT USER APPROVAL.
begin;

-- RLS helper stays out of PostgREST-exposed schemas; it is an invoker,
-- NOT a definer, and thus can only see RLS-scoped staff membership rows.
create schema if not exists newsroom_private;
revoke all on schema newsroom_private from public, anon;
grant usage on schema newsroom_private to authenticated;

create function newsroom_private.scope_matches(
  p_scope text,
  p_story_id uuid,
  p_resource_owner_auth_id uuid,
  p_membership_id uuid,
  p_auth_user_id uuid
) returns boolean language sql stable security invoker set search_path = ''
as $fn$
  select case p_scope
    when 'all' then true
    when 'assigned' then p_story_id is not null and exists (
      select 1 from public.staff_story_assignments a
      where a.story_id = p_story_id
        and a.membership_id = p_membership_id
        and a.status = 'active'
    )
    when 'own' then p_resource_owner_auth_id is not null
      and p_resource_owner_auth_id = p_auth_user_id
    else false
  end;
$fn$;

create function newsroom_private.has_staff_permission(
  p_capability public.staff_capability_key,
  p_story_id uuid default null,
  p_resource_owner_auth_id uuid default null
) returns boolean language sql stable security invoker set search_path = ''
as $fn$
  select coalesce((
    select
      -- A scoped explicit DENY always takes precedence over role grants and
      -- scoped individual ALLOW. Invalid status and expired grants deny.
      not exists (
        select 1 from public.staff_capability_overrides o
        where o.membership_id = m.id
          and o.capability_key = p_capability
          and o.effect = 'deny'
          and (o.expires_at is null or o.expires_at > now())
          and newsroom_private.scope_matches(
            o.scope, p_story_id, p_resource_owner_auth_id, m.id, m.auth_user_id
          )
      )
      and (
        exists (
          select 1 from public.staff_member_roles mr
          join public.staff_role_capabilities c
            on c.role_preset_id = mr.role_preset_id
          where mr.membership_id = m.id
            and (mr.expires_at is null or mr.expires_at > now())
            and c.capability_key = p_capability
            and newsroom_private.scope_matches(
              c.scope, p_story_id, p_resource_owner_auth_id, m.id, m.auth_user_id
            )
        )
        or exists (
          select 1 from public.staff_capability_overrides o
          where o.membership_id = m.id
            and o.capability_key = p_capability
            and o.effect = 'allow'
            and (o.expires_at is null or o.expires_at > now())
            and newsroom_private.scope_matches(
              o.scope, p_story_id, p_resource_owner_auth_id, m.id, m.auth_user_id
            )
        )
      )
    from public.staff_memberships m
    where m.auth_user_id = (select auth.uid())
      and m.status = 'active'
      and (m.expires_at is null or m.expires_at > now())
      and p_capability not in (
        'reader.personal'::public.staff_capability_key,
        'settings.security_admin'::public.staff_capability_key
      )
      -- These named capabilities are intrinsically scoped even when an
      -- administrator accidentally configures their grants as 'all'.
      and (
        p_capability not in (
          'story.view_assigned'::public.staff_capability_key,
          'story.edit_assigned'::public.staff_capability_key,
          'revision.edit_assigned'::public.staff_capability_key,
          'calendar.view_assigned'::public.staff_capability_key
        ) or exists (
          select 1 from public.staff_story_assignments a
          where a.story_id = p_story_id and a.membership_id = m.id
            and a.status = 'active'
        )
      )
      and (
        p_capability <> 'media.edit_own'::public.staff_capability_key
        or p_resource_owner_auth_id = (select auth.uid())
      )
    limit 1
  ), false);
$fn$;

revoke all on function newsroom_private.scope_matches(
  text,uuid,uuid,uuid,uuid
) from public, anon, authenticated;
revoke all on function newsroom_private.has_staff_permission(
  public.staff_capability_key,uuid,uuid
) from public, anon, authenticated;
grant execute on function newsroom_private.scope_matches(
  text,uuid,uuid,uuid,uuid
) to authenticated;
grant execute on function newsroom_private.has_staff_permission(
  public.staff_capability_key,uuid,uuid
) to authenticated;

-- Restrict direct authenticated UPDATE transitions and privileged columns.
-- This is a narrow defense for user-session PostgREST DML. The existing
-- SECURITY DEFINER publisher and trusted service_role write paths need their
-- own reviewed guards in CT-02f and are NOT made safe by this trigger.
create function newsroom_private.guard_story_update()
returns trigger language plpgsql security invoker set search_path = ''
as $fn$
begin
  if current_user <> 'authenticated' then return new; end if;

  if not (
    newsroom_private.has_staff_permission('story.edit_all',old.id)
    or newsroom_private.has_staff_permission('story.edit_assigned',old.id)
  ) then
    raise exception 'Current staff edit permission required' using errcode='42501';
  end if;

  if (old.status = 'published' or new.status = 'published') and
     not newsroom_private.has_staff_permission('story.publish',old.id) then
    raise exception 'Publishing permission required for live content'
      using errcode='42501';
  end if;

  if (new.author_id is distinct from old.author_id
    or new.editor_id is distinct from old.editor_id)
    and not newsroom_private.has_staff_permission('story.assign',old.id) then
    raise exception 'Story assignment change denied' using errcode='42501';
  end if;

  if (new.slug is distinct from old.slug
    or new.access_level is distinct from old.access_level
    or new.originally_published_at is distinct from old.originally_published_at
    or new.published_at is distinct from old.published_at)
    and not newsroom_private.has_staff_permission('story.publish',old.id) then
    raise exception 'Protected publication metadata change denied'
      using errcode='42501';
  end if;

  if new.scheduled_at is distinct from old.scheduled_at and
     not newsroom_private.has_staff_permission('story.schedule',old.id) then
    raise exception 'Schedule update denied' using errcode='42501';
  end if;

  if new.status is distinct from old.status then
    if new.status = 'scheduled' and
       not newsroom_private.has_staff_permission('story.schedule',old.id) then
      raise exception 'Scheduling denied' using errcode='42501';
    end if;
    if new.status = 'archived' and
       not newsroom_private.has_staff_permission('story.archive_delete',old.id) then
      raise exception 'Archiving denied' using errcode='42501';
    end if;
    if new.status = 'in_review' and not (
      newsroom_private.has_staff_permission('story.submit_review',old.id)
      or newsroom_private.has_staff_permission('story.review',old.id)
    ) then
      raise exception 'Review submission denied' using errcode='42501';
    end if;
  end if;
  return new;
end;
$fn$;

create function newsroom_private.guard_revision_write()
returns trigger language plpgsql security invoker set search_path = ''
as $fn$
begin
  if current_user <> 'authenticated' then return new; end if;
  if tg_op = 'UPDATE' and new.story_id is distinct from old.story_id then
    raise exception 'Moving a revision to another story is forbidden'
      using errcode='42501';
  end if;

  if not (
    newsroom_private.has_staff_permission('story.edit_all',new.story_id)
    or newsroom_private.has_staff_permission('revision.edit_assigned',new.story_id)
  ) then
    raise exception 'Current revision edit permission required'
      using errcode='42501';
  end if;

  if tg_op = 'INSERT' then
    if new.created_by is distinct from (select auth.uid()) then
      raise exception 'Revision creator must match current account'
        using errcode='42501';
    end if;
  end if;

  if new.status in ('published','scheduled','archived') and
    not newsroom_private.has_staff_permission('story.publish',new.story_id) then
    raise exception 'Cannot set live revision status' using errcode='42501';
  end if;

  if tg_op = 'UPDATE' then
    if (new.author_id is distinct from old.author_id
      or new.editor_id is distinct from old.editor_id) and
       not newsroom_private.has_staff_permission('story.assign',new.story_id) then
      raise exception 'Cannot reassign a revision' using errcode='42501';
    end if;
    if (new.slug is distinct from old.slug
      or new.access_level is distinct from old.access_level
      or new.originally_published_at is distinct from old.originally_published_at)
      and not newsroom_private.has_staff_permission('story.publish',new.story_id) then
      raise exception 'Cannot change protected revision metadata'
        using errcode='42501';
    end if;
    if new.scheduled_at is distinct from old.scheduled_at and
       not newsroom_private.has_staff_permission('story.schedule',new.story_id) then
      raise exception 'Cannot schedule a revision' using errcode='42501';
    end if;
  end if;
  return new;
end;
$fn$;

create trigger ct02e_guard_story_update
  before update on public.stories for each row
  execute function newsroom_private.guard_story_update();
create trigger ct02e_guard_revision_write
  before insert or update on public.story_revisions for each row
  execute function newsroom_private.guard_revision_write();

revoke all on function newsroom_private.guard_story_update()
  from public,anon,authenticated;
revoke all on function newsroom_private.guard_revision_write()
  from public,anon,authenticated;
-- Trigger functions do not require direct EXECUTE grants for authenticated.

-- Preserve published public story SELECT policy EXACTLY as restored.
-- Remove the legacy is_editor / is_author direct access policies.
drop policy if exists stories_select_editor on public.stories;
drop policy if exists stories_select_own_author on public.stories;
drop policy if exists stories_insert_staff on public.stories;
drop policy if exists stories_update_editor on public.stories;
drop policy if exists stories_update_own_author on public.stories;
drop policy if exists stories_delete_editor on public.stories;

create policy ct02e_stories_select_staff
on public.stories for select to authenticated using (
  newsroom_private.has_staff_permission('story.view_all',id)
  or newsroom_private.has_staff_permission('story.view_assigned',id)
  or newsroom_private.has_staff_permission('story.edit_all',id)
  or newsroom_private.has_staff_permission('story.edit_assigned',id)
);

create policy ct02e_stories_insert_staff
on public.stories for insert to authenticated with check (
  newsroom_private.has_staff_permission('story.create',id)
  and created_by = (select auth.uid())
  and (author_id is null or author_id = (select auth.uid())
    or newsroom_private.has_staff_permission('story.assign',id))
  and (
    status in ('draft','in_review')
    or (status='published' and newsroom_private.has_staff_permission('story.publish',id))
    or (status='scheduled' and newsroom_private.has_staff_permission('story.schedule',id))
    or (status='archived' and newsroom_private.has_staff_permission('story.archive_delete',id))
  )
);

create policy ct02e_stories_update_staff
on public.stories for update to authenticated using (
  newsroom_private.has_staff_permission('story.edit_all',id)
  or newsroom_private.has_staff_permission('story.edit_assigned',id)
) with check (
  newsroom_private.has_staff_permission('story.edit_all',id)
  or newsroom_private.has_staff_permission('story.edit_assigned',id)
);

create policy ct02e_stories_delete_staff
on public.stories for delete to authenticated using (
  newsroom_private.has_staff_permission('story.archive_delete',id)
);

drop policy if exists "Editorial staff can read story revisions" on public.story_revisions;
drop policy if exists "Editorial staff can create story revisions" on public.story_revisions;
drop policy if exists "Editorial staff can update story revisions" on public.story_revisions;
drop policy if exists "Editorial staff can delete story revisions" on public.story_revisions;

create policy ct02e_revisions_select_staff
on public.story_revisions for select to authenticated using (
  newsroom_private.has_staff_permission('story.view_all',story_id)
  or newsroom_private.has_staff_permission('revision.view',story_id)
  or newsroom_private.has_staff_permission('story.view_assigned',story_id)
  or newsroom_private.has_staff_permission('story.edit_all',story_id)
  or newsroom_private.has_staff_permission('revision.edit_assigned',story_id)
);

create policy ct02e_revisions_insert_staff
on public.story_revisions for insert to authenticated with check (
  created_by = (select auth.uid())
  and (
    newsroom_private.has_staff_permission('story.edit_all',story_id)
    or newsroom_private.has_staff_permission('revision.edit_assigned',story_id)
  )
);

create policy ct02e_revisions_update_staff
on public.story_revisions for update to authenticated using (
  newsroom_private.has_staff_permission('story.edit_all',story_id)
  or newsroom_private.has_staff_permission('revision.edit_assigned',story_id)
) with check (
  newsroom_private.has_staff_permission('story.edit_all',story_id)
  or newsroom_private.has_staff_permission('revision.edit_assigned',story_id)
);

create policy ct02e_revisions_delete_staff
on public.story_revisions for delete to authenticated using (
  newsroom_private.has_staff_permission('revision.discard',story_id)
);

commit;
